CREATE TABLE IF NOT EXISTS exercises (
  id TEXT PRIMARY KEY, name_en TEXT NOT NULL, name_ht TEXT, category TEXT, equipment TEXT,
  primary_muscles TEXT, secondary_muscles TEXT, demo_key TEXT, loop_key TEXT, poster_key TEXT,
  demo_duration_s REAL, loop_duration_s REAL, created_at TEXT DEFAULT CURRENT_TIMESTAMP
);

